import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 14 章 资讯与信息流：收集、筛选、汇总（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第14章 资讯与信息流：收集、筛选、汇总（易懂版）.md","filePath":"easy/第14章 资讯与信息流：收集、筛选、汇总（易懂版）.md"}'),l={name:"easy/第14章 资讯与信息流：收集、筛选、汇总（易懂版）.md"};function s(n,t,i,u,h,_){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-14-章-资讯与信息流-收集、筛选、汇总-易懂版" tabindex="-1">第 14 章 资讯与信息流：收集、筛选、汇总（易懂版） <a class="header-anchor" href="#第-14-章-资讯与信息流-收集、筛选、汇总-易懂版" aria-label="Permalink to &quot;第 14 章 资讯与信息流：收集、筛选、汇总（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 14 章 资讯与信息流：收集、筛选、汇总（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 14 章 资讯与信息流：收集、筛选、汇总.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>天天被信息轰炸？让我当你的&quot;信息助理&quot;——帮你捞重点、去噪音、出摘要。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>你订阅了 50 个公众号，但每天只看 10 分钟。这时候你需要一个助理：<strong>先把 50 篇看一遍，挑出 5 篇真值得看的，每篇给你 3 行摘要。</strong></p><p>这就是我在信息流里的角色。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>收集</strong>：你给来源（链接、文档、文件夹、网页），我帮你把相关内容捞出来。</li><li><strong>筛选</strong>：按你的标准过滤——只看某主题？只看某时间段？只要超过某重要程度？</li><li><strong>汇总</strong>：把零散信息整理成&quot;一份摘要/一张表/一份报告&quot;。</li></ol><h2 id="关键-先定义-什么算重要" tabindex="-1">关键：先定义&quot;什么算重要&quot; <a class="header-anchor" href="#关键-先定义-什么算重要" aria-label="Permalink to &quot;关键：先定义&quot;什么算重要&quot;&quot;">​</a></h2><p>同样一堆资讯，&quot;老板看&quot;和&quot;运营看&quot;的筛选标准完全不同。所以要告诉我说：</p><ul><li><strong>关心的主题</strong>：AI 行业动态？竞品动作？政策法规？</li><li><strong>关心的维度</strong>：时间？金额？人物？趋势？</li><li><strong>要什么形式</strong>：3 行摘要？对比表？周报？</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;这 10 篇文章是关于 AI 应用的，帮我筛出和&#39;办公提效&#39;相关的，每篇用 3 句话概括：讲什么、能怎么用、适合谁。&quot;</p><p><strong>你会看到</strong>：我通读 → 筛出相关 → 逐篇概括 → 输出一张汇总表。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 让我&quot;看新闻&quot;却不给来源——<strong>我没法自己漫游全网</strong>（除非你给了工具和权限）；</li><li>❌ 不给筛选标准——<strong>我会默认按最普通的标准筛，未必合你意</strong>；</li><li>❌ 把摘要当原文——<strong>重要内容，摘要后务必回原文核对</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>信息处理 = 你给来源 + 说清标准 + 我筛选汇总 + 你回原文核关键。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下次攒了一堆&quot;待读文章&quot;，别硬啃——<strong>把链接发我，说&quot;筛出和 XX 相关的，各 3 句摘要&quot;。</strong></p><p>👉 [下一章：自动化工作流，让任务自己跑（易懂版）](第15章 自动化工作流：让任务自己跑（易懂版）.md)</p>',21)])])}const c=o(l,[["render",s]]);export{q as __pageData,c as default};
